from pathlib import Path
import json
W=Path(__file__).resolve().parent;S=W/'source/programs/pump-amm/src'
def ref(f,t):
 s=(S/f).read_text();return {'path':'programs/pump-amm/src/'+f,'line':s[:s.index(t)].count('\n')+1}
rows=[]
def add(n,f,token,context,auth,effect,limit):
 rows.append({'instruction':n,'evidence_class':'static-only'if n=='create_config'else'runtime-bounded','entry':ref('lib.rs','pub fn '+n),'body':ref(f,token),'context':ref(*context),'authorization_accounts':auth,'conservation_order':effect,'limits':limit})
admin='Owned GlobalConfig plus has_one admin signer; canonical address explicit only in selected contexts. Unique initializer creates global_config PDA.'
for n,ctx in [('update_fee_config','AdminGlobal'),('update_buyback_config','AdminGlobal'),('toggle_mayhem_mode','AdminGlobal'),('toggle_cashback_enabled','AdminGlobal'),('toggle_boost','AdminGlobalNoEvent'),('update_admin','UpdateAdmin'),('disable','AdminGlobal'),('set_reserved_fee_recipients','SetReservedFeeRecipients'),('update_creator_fee_config','UpdateCreatorFeeConfig'),('set_boost_authority','SetBoostAuthority')]:
 add(n,'lib.rs','pub fn '+n,('lib.rs','pub struct '+ctx+"<'info>"),admin,'Fee setters each <=1000; recipient sets validated; buyback<=10000; flags and new authority values stored. Resize-capable setters fund/reralloc949 before state update; events where declared.','Privileged policy: zero replacement admin/boost authority or arbitrary max configurable creator fee can lock or impair paths. Short layouts can fail exit; no outsider escalation shown.')
add('create_config','lib.rs','pub fn create_config',('instructions/admin/create_config.rs','pub struct CreateConfig'),'Fixed administrator signer, canonical global_config PDA init949.','Scalar setters <=1000 and sorted unique nonzero recipients before event; other fields default.','Static-only source and compiled inclusion; no authentic successful fixed-admin runtime replay.')
add('create_pool','create.rs','pub fn execute',('create.rs','pub struct CreatePool'),'Creator signer; canonical pool tuple PDA and LP mint PDA; vault ATAs; typed token programs; supported mints.','Positive inputs, different mints, flags/canonical mode checks; token deposits then reload; geometric liquidity sqrt with100 locked; LP mint; serialize pool/event.','Fee overrides/can-edit only constrained to canonical Pump signer, not globally bounded here. Any late failure requires transaction rollback. Only metadata token extensions admitted by this creator.')
for n in ['deposit','withdraw']:
 add(n,'lib.rs','fn liquidity',('lib.rs','pub struct Liquidity'),'User signer; owned pool has_one mints/LP/vaults; LP account user authority; token programs fixed.','Reserve ratio rounding up for deposit/down withdraw; exclude accrued quote fees; quote transfer-fee adjustment; token move then LP mint/burn and supply/virtual state.','Pool PDA authority enforced by signer/CPI and stored seeds rather than context seeds. Zero/alias/old supply paths may fail; token policy differs from historical pools.')
for n in ['buy','buy_exact_quote_in']:
 add(n,'legacy_buy.rs','pub fn execute',('legacy_buy.rs','pub struct LegacyBuy'),'User signer; pool has_one mints/vaults; typed fixed Fees CPI + fee PDA; protocol recipient membership; ATA destinations/remaining buyback keys checked.','Disable flag, optional growth, fee CPI, constant-product arithmetic/slippage; output base first then pool/protocol/creator/buyback quote payments; event.','track_volume only emitted locally, no new-volume accrual here; no full external Fees/active-incentive correspondence proved. Failed later checks rely rollback; return-data producer ID not checked locally.')
add('sell','legacy_sell.rs','pub fn execute',('legacy_sell.rs','pub struct LegacySell'),'Same pool/user/fixed Fees checks as legacy buy; creator and cashback addresses/owners checked.','Gross base pricing; fee deductions; explicit curve-lp<=real-excluded-fees guard; base deposit, user quote, fee payouts, event.','Base input conservation assumes supported token behavior; external fee response trusted. Late remaining-account checks can fail after CPI.')
for n in ['buy_v2','sell_v2','buy_exact_quote_in_v2']:
 add(n,'trade.rs','pub fn execute',('trade.rs','pub struct TradeV2'),'User signer; pool has_one mints/vaults; owned external FeeConfig PDA; token programs constrained; buyback token owner/mint/ATA/authorized wallet checked.','Inline fee selection and constant-product math; slippage and quote fee adjustments; pool liability accrual and virtual reserve reduction.','Sell lacks legacy real-reserve-minus-liabilities bound for positive virtual reserves (A1). prepare rejects cashback but not mayhem. Exact external/token/layout equivalence unproved.')
add('multi_hop_swap','multi_hop.rs','pub fn execute',('multi_hop.rs','pub struct MultiHop'),'User signer; canonical global/fee/accumulator; groups of5 with continuous mints and uniform direction; AMM owned typed contexts; Pump target fixed.','Route into AMM or grouped Pump; signs config/previous pool seeds; verifies Pump return producer/16-byte response and selected before-after balances; per-hop exit; final minimum.','AMM legs require canonical/no cashback/no mayhem but allow boost virtual state; reserve guard A1. Native Pump balance cases delegated; repeated/alias routes not exhaustively proved.')
add('init_boost','boost.rs','pub fn execute',('boost.rs','pub struct InitBoost'),'Creator signer must equal Pump pool-authority derived from mint to proceed; canonical global; pool/vault mint links.','No-op on wrong signer/state/disabled; move calculated quote slice to canonical boost ATA; set virtual; reload/event.','Overflowed effective calculation is treated as None and does not trigger nonzero no-op; malformed state reachability unproved; Pump signer trust.')
add('boost_buy_and_burn','boost_burn.rs','pub fn execute',('boost_burn.rs','pub struct BoostBuyAndBurn'),'Configured nonzero boost authority signer; canonical global and boost-vault PDA/ATA; pool mints/vaults.','Clamp requested to boost balance; net quote fee then price; move quote, burn base, reload; two events; optional fee harvest and vault close.','Quote writable/harvest/close failure can occur after events; requires atomic rollback. Base/quote extension support externally dependent.')
for n,f,token,ctx in [('claim_cashback','cashback.rs','pub fn claim','ClaimCashback'),('claim_token_incentives','incentives.rs','pub fn claim','ClaimTokenIncentives')]:
 add(n,f,token,(f,'pub struct '+ctx),'Permissionless payer/user key; canonical user accumulator; destination token authority/mint fixed to user; global incentive vault/PDA for reward claim.','Cashback sweeps full vault and checked total; incentive updates elapsed bucket/reward then transfers unclaimed and resets totals; both emit.','No user signature required because payout destination constrained. Incentive period/index assumptions can panic; close/reset forfeiture is user-authorized. Nominal gross token counts.')
for n,ctx in [('init_user_volume_accumulator','InitUserVolumeAccumulator'),('close_user_volume_accumulator','CloseUserVolumeAccumulator')]:
 add(n,'lib.rs','pub fn '+n,('lib.rs','pub struct '+ctx),'Init permissionless payer+user key/PDA; close requires user signer/PDA and refunds user.','Init_if_needed size137 then clock/event and user assignment; close event followed by generated close.','Closing can discard unclaimed state by user choice; no third-party close. Init existing accumulator preserves counters.')
add('sync_user_volume_accumulator','incentives.rs','pub fn sync',('incentives.rs','pub struct SyncUserVolumeAccumulator'),'Permissionless user key; canonical owned global and user accumulators.','Resets prior total claimed only when both timestamps predate start; event only on change.','Epoch/schedule policy and timestamps are trusted; no payout redirect.')
add('admin_update_token_incentives','incentives.rs','pub fn admin',('incentives.rs','pub struct AdminUpdateTokenIncentives'),'Canonical global has_one admin signer; global accumulator PDA; canonical incentive ATA creation.','Set mint/day period before conditional range checks;30 buckets; checked/unchecked index/conversion operations; event.','Zero/negative/extreme period can be stored on zero start/end and no-supply path; later claim/index arithmetic may panic (A2).')
add('collect_coin_creator_fee','collect.rs','pub fn execute',('collect.rs','pub struct CollectCoinCreatorFee'),'Permissionless; creator vault PDA+canonical ATA; destination token mint/authority creator; reject Fee-owned migrated creator.','Zero-balance no-op otherwise full source transfer signed creator-vault; event.','Payout recipient constrained despite no signature; token program enforces spending state.')
for n,token,ctx in [('transfer_creator_fees_to_pump','pub fn legacy','TransferCreatorFeesToPump'),('transfer_creator_fees_to_pump_v2','pub fn v2','TransferCreatorFeesToPumpV2')]:
 add(n,'transfer_creator.rs',token,('transfer_creator.rs','pub struct '+ctx+"<'info>"),'Permissionless; canonical AMM creator vault and Pump destination PDA; token ATA constraints; V2 payer signer.','Native close/recreate vault then move remaining authority lamports, with destination-data rent threshold; V2 token ATA create then full transfer.','All recipient addresses fixed by creator; legacy threshold/no-op and destination ownership behavior depend System/token CPI; no arbitrary redirect.')
for n in ['sweep_protocol_fee','sweep_creator_fee']:
 add(n,'sweep.rs','pub fn execute',('sweep.rs','pub struct SweepFees'),'Payer signer; owned pool quote links; protocol configured recipient or creator-vault PDA; recipient canonical ATA.','Resize287; verify vault covers both liabilities; zero no-op; transfer selected bucket, increase virtual offset and clear liability, event.','Global canonical uniqueness assumption; alias guard checks source authority; external token semantics and late errors remain conditional.')
add('admin_cto_pool','creator_reassignment.rs','pub fn admin_cto',('creator_reassignment.rs','pub struct AdminCtoPool'),'Pump-derived pool authority signer and pool creator equality; payer funds resize; config owner.','Reject mayhem, immutable holder policy; optional creator fee policy; creator fees must be zero; assign creator/flags/event.','Trust delegated Pump authorization; high max fee is privileged configuration. No direct external signer bypass shown.')
add('migrate_pool_coin_creator','creator_reassignment.rs','pub fn migrate',('creator_reassignment.rs','pub struct MigratePoolCoinCreator'),'Permissionless; canonical pool; Fees-owned sharing PDA mint and admin match current creator.','Reject holder reward/nonzero creator fees; migrate creator to sharing address/event.','Sharing status/admin_revoked/version not checked here; external policy intent unresolved, not an unauthorized mutation conclusion.')
add('set_coin_creator','creator_reassignment.rs','pub fn set',('creator_reassignment.rs','pub struct SetCoinCreator'),'Permissionless; owned pool; canonical Metaplex metadata and Pump curve; pool creator must be canonical.','No-op if creator nonzero; first metadata creator if Some, otherwise curve creator; event.','Some(empty) metadata vector panics; ignores creator verified flag by design; attribution policy unclear (A4).')
add('extend_account','extend.rs','pub fn execute',('extend.rs','pub struct ExtendAccount'),'Permissionless signer funds; explicit AMM owner and supported discriminator.','Select target size, no-op if already large; rent-minimum delta then realloc; event.','No PDA check; owner/discriminator and other writer constraints determine applicability. Existing excess funding still charged delta.')
D=json.loads((W/'dispatch.json').read_text());assert len(rows)==38 and {r['instruction']for r in rows}=={r['name']for r in D}
rows.sort(key=lambda x:x['instruction']);(W/'coverage.json').write_text(json.dumps(rows,indent=2)+'\n')
def loc(x):return f"`{x['path']}:{x['line']}`"
s='# AMM current-source coverage\n\n37 runtime-bounded handlers plus separately labeled static-only create_config. Runtime-bounded describes existing finite evidence, not exhaustive security verification. Every row is current candidate source only.\n\n|Instruction / evidence / source|Authorization and account checks|Conservation and failure order|Limits|\n|---|---|---|---|\n'
for r in rows:s+=f"|`{r['instruction']}` ({r['evidence_class']})<br>{loc(r['body'])}<br>{loc(r['context'])}|{r['authorization_accounts']}|{r['conservation_order']}|{r['limits']}|\n"
(W/'COVERAGE.md').write_text(s)
